package com.bank.lifecycle.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;

@Service
public class PartitionLifecycleService {
    private static final Logger log = LoggerFactory.getLogger(PartitionLifecycleService.class);
    private static final DateTimeFormatter P = DateTimeFormatter.ofPattern("yyyy_MM");
    private final JdbcTemplate jdbc;

    public PartitionLifecycleService(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    // Pre-create next month's partition BEFORE inserts need it.
    public void createPartitionFor(LocalDate month) {
        LocalDate start = month.withDayOfMonth(1);
        LocalDate end = start.plusMonths(1);
        String name = "transactions_" + start.format(P);
        jdbc.execute(String.format(
            "CREATE TABLE IF NOT EXISTS %s PARTITION OF transactions " +
            "FOR VALUES FROM ('%s') TO ('%s')", name, start, end));
        log.info("Pre-created partition {} for {}..{}", name, start, end);
    }

    // Archive then drop a month past retention — cheap metadata ops, no mass DELETE.
    public void retire(LocalDate month) {
        String name = "transactions_" + month.withDayOfMonth(1).format(P);
        // 1. detach so it leaves the live table (now a standalone table)
        jdbc.execute("ALTER TABLE transactions DETACH PARTITION " + name);
        log.info("Detached {} — archive it to cold storage next", name);
        // 2. (archive step: COPY to S3 / move to archive DB — ensure durable BEFORE drop)
        // 3. drop the whole month instantly (no row scan, no bloat)
        jdbc.execute("DROP TABLE " + name);
        log.warn("Dropped {} after archival — retention enforced cheaply", name);
    }
}
