package com.bank.lifecycle.scheduler;

import com.bank.lifecycle.service.PartitionLifecycleService;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import java.time.LocalDate;

@Component
public class RetentionScheduler {
    private final PartitionLifecycleService svc;
    private final int retentionMonths = 84;   // 7 years

    public RetentionScheduler(PartitionLifecycleService svc) { this.svc = svc; }

    // Monthly: make next month's partition, retire the one past the retention edge.
    @Scheduled(cron = "0 0 2 1 * *")   // 02:00 on the 1st of each month
    public void rollPartitions() {
        svc.createPartitionFor(LocalDate.now().plusMonths(1));
        svc.retire(LocalDate.now().minusMonths(retentionMonths));
    }
}
